input.script:
first = boundary retry 2 {
    return list_tickets({ page: 1, status: "open" })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 2 { return list_tickets({ page, status: "open" }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
listing = fold acc = first.items for page in remaining { return acc + page }

cutoff = time.parse("2026-06-03T00:00:00Z")

checked = for ticket in listing {
    detail = boundary retry 2 { return get_ticket({ id: ticket.id }) } catch err {
        return fail("GET_FAILED", err.code + ": " + err.message)
    }
    created = time.parse(detail.created_at)
    body = text.lower(detail.body if detail.body != null else "")
    skip if not (created < cutoff and "refund" in body)
    updated = boundary retry 2 {
        return update_ticket({ id: ticket.id, priority: "high", add_tags: ["billing-escalation"] })
    } catch err {
        return fail("UPDATE_FAILED", err.code + ": " + err.message)
    }
    return { id: ticket.id }
}

ids = for row in checked { return row.id }
submission = submit_result({ answer: { escalated_ticket_ids: ids } })
return { escalated: ids, recorded: submission.recorded }
